import numpy as np
import pandas as pd

def task_func(arr):
    # Find minimum and maximum of the array
    min_val = arr.min()
    max_val = arr.max()

    # If all values are the same, return zeros
    if max_val == min_val:
        scaled_values = np.zeros_like(arr, dtype=float)
    else:
        scaled_values = (arr - min_val) / (max_val - min_val)

    # Return the result as a DataFrame with the required column name
    return pd.DataFrame({'Scaled Values': scaled_values})

